        def wrapper(*args: Any, bound_fn: Callable[..., Any] = fn, **kwargs: Any) -> Any:
            return bound_fn(*args, **kwargs)
        wrapper.__name__ = name
        wrapper.__qualname__ = name
        mcp.tool(name=name)(wrapper)

